// Local source-inspection witness only; synthetic Chat leaf, no AI/governance claim.
import { useEffect } from 'react';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import DashboardLayout from './layout';
const { delivered } = vi.hoisted(() => ({ delivered: vi.fn() }));
vi.mock('next/navigation', () => ({ usePathname: () => '/home', useRouter: () => ({ push: vi.fn(), replace: vi.fn() }), useSearchParams: () => ({ get: () => null, toString: () => '' }) }));
vi.mock('@/lib/hooks/useAuth', () => ({ useAuth: () => ({ userRole: 'admin', userName: 'Fixture', permissions: {}, handleLogout: vi.fn(), impersonation: null, endImpersonation: vi.fn() }) }));
vi.mock('@/lib/hooks/useModals', () => ({ useModals: () => ({ closeAllModals: vi.fn(), openModal: vi.fn(), closeModal: vi.fn() }) }));
vi.mock('@/lib/store', () => ({ useExecutionStore: () => ({ executions: [] }) }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { providers: {alibaba:{apiKey:'local-synthetic-key',selectedModel:'qwen-plus'}}, preferences: { defaultProvider: 'alibaba' } }, updateProvider: vi.fn(), updatePreferences: vi.fn() }) }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (s: string) => s }) }));
vi.mock('@/components/CompactHeader', () => ({ default: () => null }));
vi.mock('@/components', async () => ({
    AgentChatWithHistory: (await import('@/components/AgentChatWithHistory')).AgentChatWithHistory,
    Sidebar: () => null, OnboardingWizard: () => null, QuickStart: () => null,
    UserContextForm: () => null, SettingsPage: () => null, AIUsagePanel: () => null,
    ApiKeyWizard: () => null, MultiAgentPanel: () => null, ToolsPage: () => null,
}));

vi.mock('@/lib/ai-providers', () => ({ createAIProvider: () => ({ chat: delivered }) }));
vi.mock('@/lib/hooks/useModelPricing', () => ({ useModelPricing: () => ({ pricing: {}, status: 'ready', updatedAt: null }) }));
vi.mock('@/lib/quota-manager', async original => ({
    ...await original<typeof import('@/lib/quota-manager')>(),
    useQuotaManager: () => ({ trackUsage: vi.fn(), checkBudget: () => ({ ok: true, remaining: { daily: Infinity, monthly: Infinity } }) }),
}));
const handoff = (prompt: string) => act(() => { window.dispatchEvent(new CustomEvent('cvf:openAgent', { detail: { prompt } })); });
const tick = (ms: number) => act(async () => { await vi.advanceTimersByTimeAsync(ms); });
const history = () => JSON.parse(localStorage.getItem('cvf_chat_history')!);
const contents = (id: string) => history().sessions.find((s: {id: string}) => s.id === id).messages.map((m: {content: string}) => m.content);
const A = 'LOCAL_REVIEW_ALPHA'; const B = 'LOCAL_REVIEW_BETA';
const saved = {id:'local-unrelated-C',title:'Untouched C',provider:'alibaba',createdAt:'2026-01-01T00:00:00.000Z',updatedAt:'2026-01-01T00:00:00.000Z',metadata:{messageCount:2},messages:[{id:'C1',role:'user',content:'UNRELATED_C',timestamp:'2026-01-01T00:00:00.000Z'},{id:'C2',role:'assistant',content:'C_REPLY',timestamp:'2026-01-01T00:00:00.000Z'}]};
describe('Local distinct actual chat receiving challenge', () => {
 beforeEach(() => {
  vi.useFakeTimers(); localStorage.clear(); document.body.style.overflow=''; delivered.mockReset();
  delivered.mockImplementation(async (m: Array<{content:string}>) => ({text:'LOCAL_REPLY:'+m[m.length-1].content,usage:{totalTokens:2}}));
  localStorage.setItem('cvf_chat_history',JSON.stringify({sessions:[saved],activeSessionId:saved.id}));
 });
 afterEach(() => { cleanup(); vi.useRealTimers(); localStorage.clear(); document.body.style.overflow=''; });
 it('retains a real unsent draft and whole history across hide/restore, then accepts repeated explicit B separately', async () => {
  const view=render(<DashboardLayout><div>Review</div></DashboardLayout>);
  handoff(A); await tick(700); const aId=history().activeSessionId;
  expect(contents(aId).slice(1)).toEqual([A,'LOCAL_REPLY:'+A]);
  fireEvent.change(screen.getByPlaceholderText('Type a message...'),{target:{value:'LOCAL_UNSENT_DRAFT'}});
  const before=history(); fireEvent.click(screen.getByRole('button',{name:'Minimize'}));
  expect(screen.getByPlaceholderText('Type a message...').closest('[hidden]')).not.toBeNull();
  view.rerender(<DashboardLayout><div>Changed unrelated child</div></DashboardLayout>);
  await tick(900); fireEvent.click(screen.getByText('agent.restoreHint'));
  expect((screen.getByPlaceholderText('Type a message...') as HTMLTextAreaElement).value).toBe('LOCAL_UNSENT_DRAFT');
  expect(history()).toEqual(before); expect(delivered).toHaveBeenCalledTimes(1);
  handoff(B); await tick(700); const bId=history().activeSessionId;
  expect(bId).not.toBe(aId); expect(contents(aId).slice(1)).toEqual([A,'LOCAL_REPLY:'+A]);
  expect(contents(bId).slice(1)).toEqual([B,'LOCAL_REPLY:'+B]);
  handoff(B); await tick(700); const secondB=history().activeSessionId;
  expect(secondB).not.toBe(bId); expect(contents(secondB).slice(1)).toEqual([B,'LOCAL_REPLY:'+B]);
  expect(contents(saved.id)).toEqual(['UNRELATED_C','C_REPLY']); expect(delivered).toHaveBeenCalledTimes(3);
 });
 it('replaces a hidden queued A by B, then closes queued C without a send or history contamination', async () => {
  render(<DashboardLayout><div>Review timer</div></DashboardLayout>);
  handoff(A); const aId=history().activeSessionId;
  fireEvent.click(screen.getByRole('button',{name:'Minimize'})); await tick(150);
  handoff(B); const bId=history().activeSessionId; await tick(700);
  expect(bId).not.toBe(aId); expect(contents(aId)).toEqual([]);
  expect(contents(bId).slice(1)).toEqual([B,'LOCAL_REPLY:'+B]);
  expect(delivered).toHaveBeenCalledTimes(1);
  handoff('LOCAL_QUEUED_C'); await tick(100);
  fireEvent.click(screen.getByRole('button',{name:'Close chat'})); await tick(900);
  expect(delivered).toHaveBeenCalledTimes(1); expect(document.body.style.overflow).toBe('');
  expect(contents(saved.id)).toEqual(['UNRELATED_C','C_REPLY']);
  expect(history().sessions.every((row: {messages: Array<{content:string}>}) => !row.messages.some(m=>m.content==='LOCAL_QUEUED_C'))).toBe(true);
 });
});
